PRAGMA foreign_keys=ON;
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE seasons(year INTEGER PRIMARY KEY,name TEXT,manual_url TEXT,analysis_markdown TEXT);
CREATE TABLE robot_dossiers(id TEXT PRIMARY KEY,year INTEGER,team INTEGER,team_name TEXT,robot_name TEXT,epa_rank INTEGER,epa REAL,epa_pre_champs REAL,architecture TEXT,analyst_inference TEXT,limits_json TEXT,coverage_json TEXT,version_audit TEXT,strict_acceptance TEXT,tags_json TEXT);
CREATE TABLE sources(id TEXT PRIMARY KEY,url TEXT UNIQUE,title TEXT,kind TEXT,review_basis TEXT,retrieved_on TEXT);
CREATE TABLE robot_sources(robot_id TEXT REFERENCES robot_dossiers(id),source_id TEXT REFERENCES sources(id),relationship TEXT,PRIMARY KEY(robot_id,source_id));
CREATE TABLE subsystems(robot_id TEXT REFERENCES robot_dossiers(id),subsystem TEXT,description TEXT,coverage_status TEXT,source_ids_json TEXT,PRIMARY KEY(robot_id,subsystem));
CREATE TABLE versions(id TEXT PRIMARY KEY,robot_id TEXT REFERENCES robot_dossiers(id),ordinal INTEGER,description TEXT,date_start TEXT,date_end TEXT,status TEXT,source_ids_json TEXT);
CREATE TABLE selection_audit(year INTEGER,team INTEGER,team_name TEXT,epa_rank INTEGER,epa REAL,selected INTEGER,reason TEXT,PRIMARY KEY(year,team));
CREATE TABLE season_epa(year INTEGER,team INTEGER,team_name TEXT,epa_rank INTEGER,epa REAL,pre_champs_epa REAL,epa_breakdown_json TEXT,PRIMARY KEY(year,team));
CREATE TABLE events(key TEXT PRIMARY KEY,year INTEGER,name TEXT,type TEXT,week INTEGER,start_date TEXT,end_date TEXT,tba_url TEXT,data_json TEXT);
CREATE TABLE matches(key TEXT PRIMARY KEY,event TEXT REFERENCES events(key),year INTEGER,comp_level TEXT,match_number INTEGER,red_teams_json TEXT,blue_teams_json TEXT,red_score REAL,blue_score REAL,winner TEXT,result_json TEXT,mirror_video_id TEXT);
CREATE TABLE team_events(team INTEGER,event TEXT REFERENCES events(key),year INTEGER,pre_elim_epa REAL,event_end_epa REAL,qual_rank INTEGER,data_json TEXT,PRIMARY KEY(team,event));
CREATE TABLE benchmarks(event TEXT PRIMARY KEY REFERENCES events(key),year INTEGER,type TEXT,week INTEGER,clean_score_median REAL,clean_score_min REAL,clean_score_max REAL,top_pre_elim_epa REAL,eighth_pre_elim_epa REAL,champion_teams_json TEXT,data_json TEXT);
CREATE TABLE einstein_reviews(key TEXT PRIMARY KEY REFERENCES matches(key),year INTEGER,review_status TEXT,video_reviewed INTEGER,tactical_review_complete INTEGER,data_json TEXT);
CREATE VIRTUAL TABLE robot_search USING fts5(robot_id UNINDEXED,content);
CREATE TABLE context_documents(id TEXT PRIMARY KEY,title TEXT,year INTEGER,robot_id TEXT REFERENCES robot_dossiers(id),kind TEXT,body_markdown TEXT,source_urls_json TEXT);
CREATE TABLE mechanism_images(id TEXT PRIMARY KEY,robot_id TEXT REFERENCES robot_dossiers(id),path TEXT,source_url TEXT,caption TEXT,publisher_label TEXT,review_status TEXT,metadata_json TEXT);
CREATE TABLE source_posts(id TEXT PRIMARY KEY,robot_id TEXT REFERENCES robot_dossiers(id),topic_id TEXT,topic_title TEXT,post_number INTEGER,author TEXT,created_at TEXT,url TEXT,navigation_tags_json TEXT,outbound_links_json TEXT,review_status TEXT);
CREATE TABLE cad_code_links(id TEXT PRIMARY KEY,robot_id TEXT REFERENCES robot_dossiers(id),discovery_post TEXT REFERENCES source_posts(id),url TEXT,kind TEXT,validation TEXT);
CREATE TABLE video_reviews(video_id TEXT PRIMARY KEY,url TEXT,title TEXT,season INTEGER,discovery_url TEXT,source_post_date TEXT,published_date TEXT,transcript_status TEXT,review_status TEXT,source_summary TEXT,transfer_analysis TEXT,reviewed_ranges_json TEXT,visual_review INTEGER,metadata_json TEXT);
CREATE VIRTUAL TABLE context_search USING fts5(document_id UNINDEXED,kind UNINDEXED,content);
CREATE INDEX matches_event ON matches(event);
CREATE INDEX robot_year_rank ON robot_dossiers(year,epa_rank);

CREATE TABLE binder_sources(id TEXT PRIMARY KEY,robot_id TEXT REFERENCES robot_dossiers(id),title TEXT,url TEXT,format TEXT,status TEXT,metadata_json TEXT);
CREATE TABLE binder_audit(robot_id TEXT PRIMARY KEY REFERENCES robot_dossiers(id),status TEXT,metadata_json TEXT);
CREATE TABLE technical_mechanisms(id TEXT PRIMARY KEY,robot_id TEXT REFERENCES robot_dossiers(id),binder_id TEXT REFERENCES binder_sources(id),subsystem TEXT,title TEXT,construction TEXT,team_stated_reason TEXT,engineering_analysis TEXT,recommended_validation TEXT,limitations TEXT,metadata_json TEXT);
CREATE TABLE technical_parameters(id TEXT PRIMARY KEY,robot_id TEXT REFERENCES robot_dossiers(id),binder_id TEXT REFERENCES binder_sources(id),component TEXT,pdf_page INTEGER,published_parameters TEXT,source_url TEXT,metadata_json TEXT);
CREATE TABLE tower_summary_2026(group_name TEXT PRIMARY KEY,metadata_json TEXT);
